html:
{% macro fmt(v) %}{{ '{:,.0f}'.format(v or 0).replace(',', ' ') }}{% endmacro %}
<style>
  .bp-page { font-family: Arial, sans-serif; color:#1a1a1a; max-width:760px; margin:0 auto; }
  .bp-header { display:flex; align-items:center; justify-content:space-between; padding-bottom:8px; border-bottom:3px solid #0E5C8A; }
  .bp-logo img { height:64px; }
  .bp-h-center { text-align:center; flex:1; }
  .bp-h-center h1 { color:#0E5C8A; font-size:20px; margin:0; letter-spacing:2px; font-weight:800; }
  .bp-h-center .slogan { color:#F77F00; font-size:10px; font-style:italic; margin:2px 0 0; }
  .bp-h-right { text-align:right; font-size:10px; color:#0E5C8A; font-weight:600; }
  .bp-h-right .bp-per { background:#0E5C8A; color:#fff; padding:4px 10px; font-weight:700; border-radius:4px; }
  .bp-block { border:1px solid #d0d7de; padding:10px 12px; border-radius:6px; background:#fafbfc; margin:14px 0; }
  .bp-block h4 { margin:0 0 6px; color:#0E5C8A; font-size:11px; text-transform:uppercase; letter-spacing:1px; border-bottom:1px solid #d0d7de; padding-bottom:4px; }
  .bp-block p { margin:2px 0; font-size:11px; display:inline-block; margin-right:22px; }
  .bp-block strong { color:#0E5C8A; }
  table.bp-t { width:100%; border-collapse:collapse; margin-top:8px; font-size:11px; }
  table.bp-t thead th { background:linear-gradient(135deg,#0E5C8A,#1976D2); color:#fff; padding:7px 10px; text-transform:uppercase; font-size:10px; letter-spacing:1px; text-align:left; }
  table.bp-t thead th.r { text-align:right; }
  table.bp-t tbody td { padding:6px 10px; border-bottom:1px solid #e2e8f0; }
  table.bp-t tbody td.r { text-align:right; }
  table.bp-t tbody tr:nth-child(even) { background:#f8fafd; }
  .bp-sub td { font-weight:700; background:#eef3f8; }
  .bp-cols { display:flex; gap:16px; }
  .bp-cols > div { flex:1; }
  .bp-net { margin-top:16px; background:linear-gradient(135deg,#2e7d32,#43a047); color:#fff; padding:12px 16px; border-radius:8px; display:flex; justify-content:space-between; align-items:center; }
  .bp-net .lbl { font-size:12px; text-transform:uppercase; letter-spacing:1px; opacity:.9; }
  .bp-net .val { font-size:22px; font-weight:800; }
  .bp-lettres { margin-top:8px; border-left:4px solid #F77F00; padding:8px 14px; background:#fff7ed; font-size:11px; font-style:italic; }
  .bp-cout { margin-top:12px; font-size:10px; color:#666; text-align:right; }
  .bp-footer { margin-top:22px; border-top:1px solid #d0d7de; padding-top:8px; text-align:center; font-size:9px; color:#666; }
  .bp-footer .slog { color:#F77F00; font-weight:700; font-style:italic; }
</style>

<div class="bp-page">
  <div class="bp-header">
    <div class="bp-logo"><img src="/assets/kya_hr/images/logo_kya.png" onerror="this.src='/files/vrai.png'"></div>
    <div class="bp-h-center">
      <h1>BULLETIN DE PAIE</h1>
      <p class="slogan">KYA, move beyond the sky!</p>
    </div>
    <div class="bp-h-right">
      <div class="bp-per">{{ doc.mois }} {{ doc.annee }}</div>
      <div style="color:#666;margin-top:4px">Ref. {{ doc.name }}</div>
    </div>
  </div>

  <div class="bp-block">
    <h4>Salarie</h4>
    <p><strong>Nom :</strong> {{ doc.employee_name or '' }}</p>
    <p><strong>Matricule :</strong> {{ doc.matricule or doc.employee }}</p>
    <p><strong>Poste :</strong> {{ doc.poste or '' }}</p>
    {% if doc.departement %}<p><strong>Departement :</strong> {{ doc.departement }}</p>{% endif %}
    <p><strong>Pers. a charge :</strong> {{ doc.nb_charges or 0 }}</p>
  </div>

  <table class="bp-t">
    <thead><tr><th style="width:70%">GAINS</th><th class="r">Montant (CFA)</th></tr></thead>
    <tbody>
      <tr><td>Salaire de base</td><td class="r">{{ fmt(doc.salaire_base) }}</td></tr>
      {% for p in doc.primes %}<tr><td>{{ p.libelle }}</td><td class="r">{{ fmt(p.montant) }}</td></tr>{% endfor %}
      <tr class="bp-sub"><td>SALAIRE BRUT TOTAL</td><td class="r">{{ fmt(doc.brut_total) }}</td></tr>
    </tbody>
  </table>

  <table class="bp-t">
    <thead><tr><th style="width:70%">RETENUES</th><th class="r">Montant (CFA)</th></tr></thead>
    <tbody>
      <tr><td>CNSS (part salariale, base {{ fmt(doc.base_cnss) }})</td><td class="r">{{ fmt(doc.cnss_salarie) }}</td></tr>
      <tr><td>IRPP (revenu imposable {{ fmt(doc.base_imposable) }})</td><td class="r">{{ fmt(doc.irpp) }}</td></tr>
      {% if doc.autres_retenues %}<tr><td>Autres retenues</td><td class="r">{{ fmt(doc.autres_retenues) }}</td></tr>{% endif %}
      <tr class="bp-sub"><td>TOTAL DES RETENUES</td><td class="r">{{ fmt(doc.total_retenues) }}</td></tr>
    </tbody>
  </table>

  <div class="bp-net">
    <span class="lbl">Net a payer</span>
    <span class="val">{{ fmt(doc.net_a_payer) }} CFA</span>
  </div>
  {% if doc.net_en_lettres %}<div class="bp-lettres">Arrete le present bulletin a la somme nette de {{ doc.net_en_lettres }}.</div>{% endif %}

  <div class="bp-cout">Charges patronales CNSS : {{ fmt(doc.cnss_patronal) }} CFA &nbsp;&middot;&nbsp; Cout total employeur : <strong>{{ fmt(doc.cout_employeur) }} CFA</strong></div>

  <div class="bp-footer">
    <p class="slog">KYA, move beyond the sky!</p>
    <p>08 BP 81101 Agoe-Logope, Lome-TOGO &middot; CNSS: 48863 &middot; NIF: 1000430317</p>
    <p style="font-size:8px;color:#999">Bulletin genere par KYA HR &mdash; a conserver sans limitation de duree.</p>
  </div>
</div>
